from fontTools.ttLib import TTFont

font_path = "fonts/MaterialSymbolsRounded-VariableFont_FILL,GRAD,opsz,wght.ttf"
target_file = 'fonts/fluent_icon_names.lua'
template = \
'''---@meta
-- This file is auto generated by tools/gen_font_glyphs.py

---@alias FluentIconFontName {font_name}

---@alias FluentIconNames
{records}
--- | string
'''

if __name__ == '__main__':
    font = TTFont(font_path)
    name_map = font['name']
    name = name_map.getBestFamilyName()

    # Get ordered list of all glyph names
    glyph_order = font.getGlyphOrder()
    print(f"Total Glyphs: {len(glyph_order)}")

    # Get best unicode-to-glyph mapping (codepoint -> glyph name)
    cmap = font.getBestCmap()
    # Invert it to map glyph name -> codepoint(s)
    glyph_to_unicode = {name: code for code, name in cmap.items()} # type: ignore

    records = [
        f'--- | \'{name}\''
        for _, name in enumerate(glyph_order)
    ]

    with open(target_file, 'w') as fp:
        fp.write(template.format(records = '\n'.join(records), font_name = f'\'{name}\''))
